use filmcraft_project::{Project,ItemId,MediaRef};use filmcraft_time::{Tick,FrameRate};use filmcraft_media::{SharedSource,generators::GeneratorSource};use filmcraft_render::{render_sequence,RenderOptions};use serde_json::{Value,json};use std::sync::Arc;
fn main(){let input:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();const T:i64=254016000000;let mut cases=vec![];
for cameras in [false,true]{for tracks in 0..4{for enabled in [false,true]{for angle in 0..5{let mut doc=input["cases"][0]["document"].clone();let mut blue=doc["project"]["items"]["1"].clone();blue["id"]=json!(99);blue["kind"]["Media"]["media"]=json!({"Generator":{"ColorMatte":{"color":[0.,0.,1.,1.]}}});doc["project"]["items"]["99"]=blue;
let source=&mut doc["project"]["items"]["6"]["kind"]["Sequence"];let mut a=source["video_tracks"][0].clone();a["id"]=json!(703);a["enabled"]=json!(tracks&1!=0);a["transitions"]=json!([]);let mut b=a.clone();b["id"]=json!(704);b["enabled"]=json!(tracks&2!=0);for clip in b["items"].as_array_mut().unwrap(){clip["id"]=json!(clip["id"].as_u64().unwrap()+10000);clip["item"]=json!(99);}source["video_tracks"]=json!([a,b]);source["multicam"]=if cameras{json!({"audio":"AllCameras","cameras":[{"name":"blue","video_track":704,"audio_tracks":[],"enabled":false},{"name":"audio","video_track":null,"audio_tracks":[]},{"name":"missing","video_track":99999,"audio_tracks":[]},{"name":"red","video_track":703,"audio_tracks":[]}]})}else{Value::Null};
let mut outer=doc["project"]["items"]["6"].clone();outer["id"]=json!(1000);let seq=&mut outer["kind"]["Sequence"];seq["multicam"]=Value::Null;seq["caption_tracks"]=json!([]);let mut track=seq["video_tracks"][0].clone();track["enabled"]=json!(true);let mut clip=track["items"][0].clone();clip["id"]=json!(20001);clip["item"]=json!(6);clip["start"]=json!(0);clip["source_in"]=json!(0);clip["duration"]=json!(10*T);clip["speed"]=json!(1.);clip["reverse"]=json!(false);clip["frame_hold"]=Value::Null;clip["effects"]=json!([]);clip["multicam"]=json!({"enabled":enabled,"angle":angle});track["items"]=json!([clip]);seq["video_tracks"]=json!([track]);doc["project"]["items"]["1000"]=outer;
let p:Project=serde_json::from_value(doc["project"].clone()).unwrap();let provider=|id:ItemId|{let(_,media,_)=p.resolve_media(id)?;let MediaRef::Generator(generator)=&media.media else{return None};Some(Arc::new(GeneratorSource::new(generator.clone(),320,200,FrameRate::new(24,1),Tick(100*T)))as SharedSource)};
for at in [0,T]{for scale in [1.,0.5]{let out=render_sequence(&p,ItemId(1000),Tick(at),RenderOptions{scale,captions:false,working_output:true,..Default::default()},&provider);cases.push(json!({"document":doc,"sequence":1000,"at":at,"cameras":cameras,"tracks":tracks,"enabled":enabled,"angle":angle,"scale":scale,"width":out.w,"height":out.h,"bits":out.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));}}
}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases}));}
